-- Changelog-item bij de SharePoint-dossiermap (zie 20260716d).

insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-16','verbeterd','Dossiers','Zelf de juiste SharePoint-map kiezen of aanmaken',
   'Vond EVA de SharePoint-map van een dossier niet, dan hield het daar op. Voortaan kun je in het tabblad Bestanden zelf de juiste map opzoeken en koppelen, of hem met één klik aanmaken als hij nog niet bestaat. Passen er meerdere mappen bij het dossier, dan laat EVA ze zien zodat je de goede aanwijst. Een map die je zelf koppelt blijft staan — EVA overschrijft je keuze niet meer.');
